1	export type Cell = [x: number, y: number];
2	
3	const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
4	  x === otherX && y === otherY;
5	
6	const neighborsOf = ([x, y]: Cell): Cell[] => [
7	  [x - 1, y - 1],
8	  [x, y - 1],
9	  [x + 1, y - 1],
10	  [x - 1, y],
11	  [x + 1, y],
12	  [x - 1, y + 1],
13	  [x, y + 1],
14	  [x + 1, y + 1],
15	];
16	
17	const countLivingNeighbors = (cell: Cell, livingCells: Cell[]): number =>
18	  neighborsOf(cell).filter((neighbor) =>
19	    livingCells.some((living) => isSameCell(neighbor, living)),
20	  ).length;
21	
22	const isLiving = (cell: Cell, livingCells: Cell[]): boolean =>
23	  livingCells.some((living) => isSameCell(cell, living));
24	
25	export const nextGeneration = (livingCells: Cell[]): Cell[] => {
26	  const candidates = [
27	    ...livingCells,
28	    ...livingCells.flatMap(neighborsOf),
29	  ].filter(
30	    (cell, index, all) =>
31	      all.findIndex((other) => isSameCell(cell, other)) === index,
32	  );
33	  return candidates.filter((cell) => {
34	    const neighbors = countLivingNeighbors(cell, livingCells);
35	    return neighbors === 3 || (neighbors === 2 && isLiving(cell, livingCells));
36	  });
37	};
